CREATE COLUMN TABLE "TEST_AP"."OWTD" ("AbsEntry" INTEGER CS_INT NOT NULL , "WTCode" NVARCHAR(4) NOT NULL , "WTName" NVARCHAR(50), "Rate" DECIMAL(21,6) CS_FIXED, "EffecDate" LONGDATE CS_LONGDATE, "Inactive" NVARCHAR(1) DEFAULT 'N', "OffclCode" NVARCHAR(15), "Category" NVARCHAR(1) DEFAULT 'P', "BaseType" NVARCHAR(1) DEFAULT 'N', "WTTypeId" INTEGER CS_INT, "BaseMin" DECIMAL(21,6) CS_FIXED, "PrctBsAmnt" DECIMAL(21,6) CS_FIXED, "FmlId" INTEGER CS_INT, "Account" NVARCHAR(15), "SlScProgr" NVARCHAR(1) DEFAULT 'N', "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWTD_WT_CODE" ON "TEST_AP"."OWTD" ( "WTCode" ASC );
CREATE INDEX "OWTD_WT_NAME" ON "TEST_AP"."OWTD" ( "WTName" ASC )